head.b:skin:
/* ══════════════════════════════════════════════════════
   FlowersOffers.com — OFFICIAL BLOGGER / BLOGSPOT THEME
   Brand Color Palette:
   - Primary:    Forest Green    #104B26 (Header, Nav, Titles, Buttons)
   - Secondary:  Floral Pink     #E91E63 (Accents, highlights, badges)
   - Accent:     Marigold Orange #F36B21 (CTAs, festive badges, stars)
   - Supporting: Leaf Green      #78B82A (Freshness badges, leaf tags)
   - Background: Pale Ivory      #FFF9EF & Pure White #FFFFFF
   - Text Dark:  Forest Charcoal #1A2E20
   - Text Muted: Green-Gray      #68756A
   - Border:     Sand Ivory      #E8E4D8
   - Button Rule: All buttons MUST have pure white text (#FFFFFF).
══════════════════════════════════════════════════════ */

:root {
  --clr-forest: #104B26;
  --clr-forest-dark: #0B351B;
  --clr-forest-light: #E8F4EC;
  --clr-pink: #E91E63;
  --clr-pink-light: #FCE4EC;
  --clr-orange: #F36B21;
  --clr-orange-hover: #D85812;
  --clr-orange-light: #FFF3EB;
  --clr-leaf: #78B82A;
  --clr-leaf-light: #F1F8E9;
  --clr-ivory: #FFF9EF;
  --clr-white: #FFFFFF;
  --clr-text-main: #1A2E20;
  --clr-text-muted: #68756A;
  --clr-border: #E8E4D8;
  --clr-border-light: #F4F0E6;

  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-hindi: 'Hind', system-ui, sans-serif;

  --shadow-sm: 0 2px 8px rgba(16, 75, 38, 0.05);
  --shadow-md: 0 8px 24px rgba(16, 75, 38, 0.08);
  --shadow-lg: 0 16px 40px rgba(16, 75, 38, 0.12);
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 9999px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background-color: var(--clr-ivory);
  color: var(--clr-text-main);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Button Rule: ALWAYS White Text */
button,
.btn,
.btn-primary,
.btn-orange,
.btn-read-more,
.btn-cta,
input[type="submit"],
a.btn {
  color: #FFFFFF !important;
  font-family: var(--font-sans);
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
}

/* ── 1. Top Announcement Bar ── */
.top-bar {
  background-color: var(--clr-forest-dark);
  color: #FFFFFF;
  font-size: 12px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(243, 107, 33, 0.3);
}
.top-bar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.top-bar-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
}
.top-bar-badge .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--clr-leaf);
  display: inline-block;
}
.top-bar-link {
  color: var(--clr-orange);
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  text-decoration: none;
}
.top-bar-link:hover {
  text-decoration: underline;
  color: #FFA726;
}

/* ── 2. Site Header & Brand Logo ── */
.site-header {
  background-color: var(--clr-white);
  border-bottom: 1px solid var(--clr-border);
  padding: 16px 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.brand-area {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}
.brand-logo-img {
  height: 46px;
  width: auto;
  object-fit: contain;
}
.brand-text-fallback {
  display: flex;
  flex-direction: column;
}
.brand-title {
  font-family: var(--font-serif);
  font-weight: 900;
  font-size: 24px;
  color: var(--clr-forest);
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.brand-title span {
  color: var(--clr-orange);
}
.brand-tagline {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--clr-text-muted);
  margin-top: 2px;
}

/* Search & Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}
.header-search {
  position: relative;
  display: none;
}
@media (min-width: 768px) {
  .header-search { display: block; }
}
.header-search input {
  width: 260px;
  padding: 9px 38px 9px 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--clr-border);
  background-color: var(--clr-ivory);
  font-size: 13px;
  color: var(--clr-text-main);
  outline: none;
  transition: all 0.2s ease;
}
.header-search input:focus {
  border-color: var(--clr-forest);
  background-color: var(--clr-white);
  box-shadow: 0 0 0 3px rgba(16, 75, 38, 0.1);
  width: 300px;
}
.header-search button {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  font-size: 14px;
  padding: 6px;
  color: var(--clr-forest);
}
.btn-shop-market {
  background-color: var(--clr-forest);
  color: #FFFFFF !important;
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(16, 75, 38, 0.2);
}
.btn-shop-market:hover {
  background-color: var(--clr-forest-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(16, 75, 38, 0.28);
}

/* ── 3. Navigation Bar ── */
.nav-bar {
  background-color: var(--clr-forest);
  color: #FFFFFF;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.nav-menu {
  display: flex;
  list-style: none;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
  padding: 0;
  margin: 0;
  scrollbar-width: none;
}
.nav-menu::-webkit-scrollbar { display: none; }
.nav-item a {
  display: block;
  padding: 12px 16px;
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
  white-space: nowrap;
  transition: all 0.2s ease;
  border-bottom: 3px solid transparent;
}
.nav-item a:hover,
.nav-item.active a {
  color: #FFFFFF;
  background-color: rgba(255, 255, 255, 0.08);
  border-bottom-color: var(--clr-orange);
}
.nav-item.special a {
  color: var(--clr-orange);
  font-weight: 700;
}

/* ── 4. Blog Hero Header Banner ── */
.blog-hero {
  background: linear-gradient(135deg, #104B26 0%, #0B351B 100%);
  color: #FFFFFF;
  padding: 48px 0;
  position: relative;
  overflow: hidden;
  margin-bottom: 40px;
  border-bottom: 4px solid var(--clr-orange);
}
.blog-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 85% 20%, rgba(243, 107, 33, 0.18) 0%, transparent 50%),
                    radial-gradient(circle at 10% 80%, rgba(120, 184, 42, 0.15) 0%, transparent 45%);
  pointer-events: none;
}
.blog-hero-inner {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  background-color: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.2);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--clr-orange);
  margin-bottom: 14px;
}
.hero-title {
  font-family: var(--font-serif);
  font-size: 36px;
  font-weight: 900;
  line-height: 1.2;
  margin-bottom: 12px;
}
@media (min-width: 768px) {
  .hero-title { font-size: 46px; }
}
.hero-subtitle {
  font-size: 16px;
  color: rgba(255, 249, 239, 0.85);
  line-height: 1.6;
  margin-bottom: 24px;
}
.hero-badges {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.hero-tag {
  background-color: rgba(255, 255, 255, 0.1);
  color: #FFFFFF;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

/* ── 5. Main Layout: Content + Sidebar ── */
.layout-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 36px;
  margin-bottom: 60px;
}
@media (min-width: 992px) {
  .layout-grid {
    grid-template-columns: 2fr 1fr;
  }
}

/* ── 6. Posts Grid (Index / Category / Search) ── */
.posts-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 28px;
}
@media (min-width: 640px) {
  .posts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.post-card {
  background-color: var(--clr-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--clr-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.25s ease, border-color 0.25s ease;
}
.post-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
  border-color: #D3E0D7;
}
.card-thumb {
  position: relative;
  width: 100%;
  height: 220px;
  overflow: hidden;
  background-color: var(--clr-forest-light);
}
.card-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.post-card:hover .card-thumb img {
  transform: scale(1.05);
}
.card-thumb-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 44px;
  background: linear-gradient(135deg, #E8F4EC 0%, #FFF3EB 100%);
}
.card-category-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background-color: var(--clr-forest);
  color: #FFFFFF !important;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.card-body {
  padding: 22px;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--clr-text-muted);
  margin-bottom: 10px;
}
.card-title {
  font-family: var(--font-serif);
  font-size: 19px;
  font-weight: 800;
  line-height: 1.35;
  color: var(--clr-text-main);
  margin-bottom: 10px;
  transition: color 0.2s ease;
}
.post-card:hover .card-title {
  color: var(--clr-forest);
}
.card-snippet {
  font-size: 13.5px;
  color: var(--clr-text-muted);
  line-height: 1.6;
  margin-bottom: 18px;
  flex: 1;
}
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--clr-border-light);
  padding-top: 14px;
}
.card-author {
  font-size: 12px;
  font-weight: 600;
  color: var(--clr-text-main);
  display: flex;
  align-items: center;
  gap: 6px;
}
.btn-read-more {
  background-color: var(--clr-forest);
  color: #FFFFFF !important;
  padding: 7px 14px;
  border-radius: var(--radius-pill);
  font-size: 12px;
  font-weight: 700;
  transition: all 0.2s ease;
  display: inline-block;
}
.btn-read-more:hover {
  background-color: var(--clr-orange);
}

/* ── 7. Single Post Page Styling ── */
.single-post-card {
  background-color: var(--clr-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--clr-border);
  padding: 32px 24px;
  box-shadow: var(--shadow-sm);
}
@media (min-width: 768px) {
  .single-post-card { padding: 44px 40px; }
}
.post-breadcrumb {
  font-size: 12px;
  color: var(--clr-text-muted);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.post-breadcrumb a { color: var(--clr-forest); font-weight: 600; }
.post-breadcrumb a:hover { text-decoration: underline; }

.single-title {
  font-family: var(--font-serif);
  font-size: 28px;
  font-weight: 900;
  line-height: 1.25;
  color: var(--clr-forest);
  margin-bottom: 16px;
}
@media (min-width: 768px) {
  .single-title { font-size: 38px; }
}

.single-meta-bar {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 13px;
  color: var(--clr-text-muted);
  padding-bottom: 20px;
  border-bottom: 1px solid var(--clr-border);
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.single-meta-item {
  display: flex;
  align-items: center;
  gap: 5px;
}

.single-featured-wrap {
  margin-bottom: 32px;
  border-radius: var(--radius-md);
  overflow: hidden;
}
.single-featured-wrap img {
  width: 100%;
  max-height: 480px;
  object-fit: cover;
}

/* Rich Post Content Typography */
.post-content {
  font-size: 16px;
  line-height: 1.8;
  color: var(--clr-text-main);
}
.post-content p {
  margin-bottom: 22px;
}
.post-content h2 {
  font-family: var(--font-serif);
  font-size: 24px;
  font-weight: 800;
  color: var(--clr-forest);
  margin: 36px 0 16px 0;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--clr-border-light);
}
.post-content h3 {
  font-family: var(--font-serif);
  font-size: 20px;
  font-weight: 700;
  color: var(--clr-text-main);
  margin: 28px 0 12px 0;
}
.post-content blockquote {
  background-color: var(--clr-ivory);
  border-left: 4px solid var(--clr-orange);
  padding: 16px 20px;
  font-style: italic;
  color: var(--clr-text-main);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  margin: 24px 0;
}
.post-content ul, .post-content ol {
  margin: 0 0 24px 24px;
  padding-left: 10px;
}
.post-content li {
  margin-bottom: 8px;
}

/* Callout CTA Box inside Post */
.post-cta-banner {
  background: linear-gradient(135deg, #104B26 0%, #0B351B 100%);
  color: #FFFFFF;
  border-radius: var(--radius-md);
  padding: 28px;
  margin: 36px 0;
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  border-left: 6px solid var(--clr-orange);
  box-shadow: var(--shadow-md);
}
.post-cta-icon {
  font-size: 40px;
  flex-shrink: 0;
}
.post-cta-info {
  flex: 1;
  min-width: 240px;
}
.post-cta-info h3 {
  font-family: var(--font-serif);
  font-size: 20px;
  font-weight: 800;
  margin-bottom: 6px;
  color: #FFFFFF;
}
.post-cta-info p {
  font-size: 13.5px;
  color: rgba(255, 249, 239, 0.85);
  margin-bottom: 12px;
}
.btn-cta-market {
  background-color: var(--clr-orange);
  color: #FFFFFF !important;
  padding: 9px 20px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: background 0.2s ease;
}
.btn-cta-market:hover {
  background-color: var(--clr-orange-hover);
}

/* Share Bar */
.social-share-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 0;
  border-top: 1px solid var(--clr-border);
  border-bottom: 1px solid var(--clr-border);
  margin: 36px 0;
  flex-wrap: wrap;
}
.share-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--clr-forest);
}
.share-btn {
  padding: 7px 14px;
  border-radius: var(--radius-pill);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #FFFFFF !important;
}
.share-btn.whatsapp { background-color: #25D366; }
.share-btn.facebook { background-color: #1877F2; }
.share-btn.twitter { background-color: #111111; }

/* ── 8. Sidebar Widgets ── */
.sidebar-widget {
  background-color: var(--clr-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--clr-border);
  padding: 24px;
  margin-bottom: 28px;
  box-shadow: var(--shadow-sm);
}
.widget-title {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 800;
  color: var(--clr-forest);
  padding-bottom: 10px;
  margin-bottom: 16px;
  border-bottom: 2px solid var(--clr-orange);
  display: flex;
  align-items: center;
  gap: 8px;
}
.about-widget-text {
  font-size: 13px;
  color: var(--clr-text-muted);
  line-height: 1.6;
  margin-bottom: 16px;
}
.sidebar-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.sidebar-pill {
  background-color: var(--clr-ivory);
  border: 1px solid var(--clr-border);
  padding: 5px 12px;
  border-radius: var(--radius-pill);
  font-size: 12px;
  font-weight: 600;
  color: var(--clr-forest);
  transition: all 0.2s ease;
}
.sidebar-pill:hover {
  background-color: var(--clr-forest);
  color: #FFFFFF !important;
  border-color: var(--clr-forest);
}

/* Festival Calendar Widget */
.festival-card {
  background-color: var(--clr-orange-light);
  border: 1px solid rgba(243, 107, 33, 0.3);
  border-radius: var(--radius-sm);
  padding: 14px;
  margin-bottom: 12px;
}
.fest-name {
  font-weight: 700;
  font-size: 14px;
  color: var(--clr-forest-dark);
}
.fest-flowers {
  font-size: 12px;
  color: var(--clr-orange);
  font-weight: 600;
  margin-top: 2px;
}

/* ── 9. Pagination ── */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  gap: 12px;
}
.blog-pager a {
  background-color: var(--clr-forest);
  color: #FFFFFF !important;
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 700;
  transition: all 0.2s ease;
}
.blog-pager a:hover {
  background-color: var(--clr-orange);
}

/* ── 10. Official Footer (Matching FlowersOffers.com) ── */
.site-footer {
  background-color: var(--clr-forest);
  color: #FFFFFF;
  padding: 60px 0 24px 0;
  margin-top: 60px;
  border-top: 4px solid var(--clr-orange);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 36px;
  margin-bottom: 48px;
}
@media (min-width: 640px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 992px) {
  .footer-grid { grid-template-columns: 2fr 1.2fr 1.2fr 1.5fr; }
}

.footer-col h4 {
  font-family: var(--font-serif);
  font-size: 16px;
  font-weight: 800;
  color: var(--clr-orange);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 18px;
}
.footer-col p {
  font-size: 13px;
  color: rgba(255, 249, 239, 0.8);
  line-height: 1.6;
  margin-bottom: 14px;
}
.footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}
.footer-links li {
  margin-bottom: 10px;
}
.footer-links a {
  font-size: 13px;
  color: rgba(255, 249, 239, 0.8);
  transition: all 0.2s ease;
}
.footer-links a:hover {
  color: var(--clr-orange);
  padding-left: 4px;
}

.footer-contact-info {
  font-size: 12.5px;
  color: rgba(255, 249, 239, 0.85);
  line-height: 1.8;
}
.footer-trust-badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  background-color: rgba(255,255,255,0.1);
  color: var(--clr-leaf);
  font-size: 11px;
  font-weight: 700;
  margin-top: 10px;
}

/* ── 11. Footer Copyright & Attribution Bar ── */
.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  padding-top: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  color: rgba(255, 249, 239, 0.7);
  text-align: center;
}
@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    text-align: left;
  }
}
.footer-bottom a {
  color: var(--clr-orange);
  font-weight: 700;
  text-decoration: none;
}
.footer-bottom a:hover {
  text-decoration: underline;
}
.footer-badges-list {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.footer-pill-tag {
  background-color: rgba(255,255,255,0.08);
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 10.5px;
  color: #FFFFFF;
  font-weight: 600;
}

/* Responsive toggles */
.mobile-menu-btn {
  display: inline-block;
  background: none;
  border: none;
  font-size: 24px;
  color: var(--clr-forest);
  cursor: pointer;
}
@media (min-width: 768px) {
  .mobile-menu-btn { display: none; }
}
